mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM organization_access.tenant_membership
    WHERE subject_id = #{subjectId}
      AND tenant_id <> #{tenantId}
      AND membership_role = 'TENANT_ADMINISTRATOR'
)

SELECT membership_id, tenant_id, subject_id, membership_role, status,
       permission_version, version, created_at
FROM organization_access.tenant_membership
WHERE tenant_id = #{tenantId}
  AND subject_id = #{subjectId}
FOR UPDATE

SELECT membership_id, tenant_id, subject_id, membership_role, status,
       permission_version, version, created_at
FROM organization_access.tenant_membership
WHERE tenant_id = #{tenantId}
  AND membership_id = #{membershipId}
FOR UPDATE

SELECT count(*)
FROM organization_access.tenant_membership
WHERE tenant_id = #{tenantId}
  AND membership_id <> #{membershipId}
  AND membership_role = 'TENANT_ADMINISTRATOR'
  AND status = 'ENABLED'

mapper.update:
UPDATE organization_access.tenant_membership
SET membership_role = #{role},
    status = #{status},
    permission_version = #{permissionVersion},
    version = #{version},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND membership_id = #{membershipId}
  AND version = #{expectedVersion}

mapper.delete:
DELETE FROM organization_access.tenant_membership_role_binding
WHERE tenant_id = #{tenantId}
  AND membership_id = #{membershipId}
